def cayley_girth(group_order, generators):
    """Compute girth of Cayley graph on Z_group_order with given generators.
    Generator set must be closed under inverse."""
    n = group_order
    adj = {i: set() for i in range(n)}
    for i in range(n):
        for g in generators:
            j = (i + g) % n
            adj[i].add(j)
            adj[j].add(i)

    from collections import deque
    best = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
                        if best <= 6:
                            return best
    return best

