import z3

def find_graph_z3(n=24, min_deg=3, max_deg=6, girth_min=7):
    # adjacency variables
    edges = {}
    for i in range(n):
        for j in range(i+1, n):
            edges[(i,j)] = z3.Bool(f"e_{i}_{j}")

    solver = z3.Solver()

    # Degree constraints
    for i in range(n):
        incident = [edges[(min(i,j), max(i,j))] for j in range(n) if j != i]
        solver.add(z3.PbGe([(v, 1) for v in incident], min_deg))
        solver.add(z3.PbLe([(v, 1) for v in incident], max_deg))

    # No cycles of length < girth_min
    # For 3-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                solver.add(z3.Not(z3.And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))

    # For 4-cycles: i-j-k-l-i (all 4 distinct)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    # 3 ways to arrange 4-cycle through these vertices
                    # i-j-k-l-i
                    solver.add(z3.Not(z3.And(edges[(i,j)], edges[(j,k)], edges[(k,l)], edges[(l,i)])))
                    # i-j-l-k-i
                    solver.add(z3.Not(z3.And(edges[(i,j)], edges[(j,l)], edges[(l,k)], edges[(k,i)])))
                    # i-k-j-l-i
                    solver.add(z3.Not(z3.And(edges[(i,k)], edges[(k,j)], edges[(j,l)], edges[(l,i)])))

    # For 5-cycles: this is many constraints (C(24,5)*12 = 42504*12 ≈ 510K)
    # Let's skip 5 and 6 cycles for now, and see if we can get a solution.
    # Then we can check girth afterward.

    print("Checking SAT (without 5,6-cycle constraints)...")
    result = solver.check()
    print(f"Result: {result}")
    if str(result) == "sat":
        model = solver.model()
        edge_list = []
        for (i,j), v in edges.items():
            if z3.is_true(model[v]):
                edge_list.append((i,j))
        return edge_list
    return None

